INSERT INTO `article` VALUES (15,'2026-08-19 17:10:22.898161','2026-08-21 11:42:18.826990','admin','admin','Voucher ShopeePay Giảm Đến 50K Dành Tặng Các Stars!','<p data-path-to-node=\"2\"><em data-path-to-node=\"2\" data-index-in-node=\"0\">Chi tiết khuyến mãi:</em></p><ul data-path-to-node=\"3\"><li><p data-path-to-node=\"3,0,0\"><strong data-path-to-node=\"3,0,0\" data-index-in-node=\"0\">Bạn mới:</strong> Giảm 20% tối đa 50.000Đ, áp dụng cho khách hàng lần đầu thanh toán dịch vụ Galaxy bằng ví ShopeePay, mỗi khách hàng được hưởng ưu đãi tối đa 1 lần trong thời gian chương trình khuyến mãi;</p></li><li><p data-path-to-node=\"3,1,0\"><strong data-path-to-node=\"3,1,0\" data-index-in-node=\"0\">Bạn thân:</strong> Giảm 10% tối đa 20.000Đ, áp dụng cho khách hàng hiện tại, mỗi khách hàng được hưởng ưu đãi tối đa 3 lần trong thời gian chương trình khuyến mãi tại các đối tác có chấp nhận thanh toán ShopeePay.</p></li></ul><p data-path-to-node=\"4\"><strong data-path-to-node=\"4\" data-index-in-node=\"0\">Lưu ý:</strong> Khách hàng cần đăng nhập vào App ShopeePay và claim voucher tại mục \"Mã Giảm giá\"</p><p><img src=\"https://www.galaxycine.vn/media/2026/7/31/shopee-x-galaxy-cinema-4_1785487810085.jpg\"></p><p data-path-to-node=\"9\"><strong data-path-to-node=\"9\" data-index-in-node=\"0\">Điều khoản chương trình:</strong></p><ul data-path-to-node=\"10\"><li><p data-path-to-node=\"10,0,0\" id=\"p-rc_b3272da9b1c5d217-27\">Mỗi tài khoản Ví ShopeePay <span class=\"citation-518 citation-519 citation-520 citation-521 citation-end-521\">tương ứng với 01 (một) tài khoản ngân hàng/ 01 (một) thiết bị di động/ 01 (một) số điện thoại.<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"1\"><!----></sup></source-footnote></span><span class=\"citation-518 citation-519 citation-520 citation-end-520\"><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"2\"><!----></sup></source-footnote></span><span class=\"citation-518 citation-519 citation-end-519\"><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"3\"><!----></sup></source-footnote></span><span class=\"citation-518 citation-end-518\"><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"4\"><!----></sup></source-footnote></span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2291380853=\"\">  <source-inline-chip _ngcontent-ng-c2291380853=\"\" _nghost-ng-c3089741741=\"\" class=\"ng-star-inserted\"></source-inline-chip></sources-carousel-inline></p><!----><!----><!----><!----><!----><!----><!----><!----></li><li><p data-path-to-node=\"10,1,0\" id=\"p-rc_b3272da9b1c5d217-28\"><span class=\"citation-514 citation-515 citation-516 citation-517 citation-end-517\">Thông tin tài khoản Ví ShopeePay (Họ tên, số điện thoại) phải trùng khớp với thông tin<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"5\"><!----></sup></source-footnote></span><span class=\"citation-514 citation-515 citation-516\"> đăng ký tài khoản ngân hàng liên kết. Trong trường hợp nghi ngờ gian lận, ShopeePay có quyền </span><span class=\"citation-513 citation-514 citation-515 citation-516 citation-end-516\">yêu<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"6\"><!----></sup></source-footnote></span><span class=\"citation-513 citation-514 citation-515 citation-end-515\"> cầu khách hàng cung cấp thông tin Chứng minh Nhân dân/ Căn cước Công dân để xác thự<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"7\"><!----></sup></source-footnote></span><span class=\"citation-513 citation-514 citation-end-514\">c.<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"8\"><!----></sup></source-footnote></span><span class=\"citation-513 citation-end-513\"><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"9\"><!----></sup></source-footnote></span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2291380853=\"\">  <source-inline-chip _ngcontent-ng-c2291380853=\"\" _nghost-ng-c3089741741=\"\" class=\"ng-star-inserted\"></source-inline-chip></sources-carousel-inline></p><!----><!----><!----><!----><!----><!----><!----><!----></li><li><p data-path-to-node=\"10,2,0\" id=\"p-rc_b3272da9b1c5d217-29\"><span class=\"citation-512\">Chương trình sẽ kết thúc khi hết ngân sách </span><span class=\"citation-510 citation-511 citation-512 citation-end-512\">khuyến mại hoặc vào hạn cuối của chương tr<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"10\"><!----></sup></source-footnote></span><span class=\"citation-510 citation-511\">ình, tùy vào điều kiện nào đ</span><span class=\"citation-508 citation-509 citation-510 citation-511 citation-end-511\">ến trước nhất.<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"11\"><!----></sup></source-footnote></span><span class=\"citation-508 citation-509 citation-510 citation-end-510\"><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"12\"><!----></sup></source-footnote></span><span class=\"citation-508 citation-509 citation-end-509\"><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"13\"><!----></sup></source-footnote></span><span class=\"citation-508 citation-end-508\"><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"14\"><!----></sup></source-footnote></span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2291380853=\"\">  <source-inline-chip _ngcontent-ng-c2291380853=\"\" _nghost-ng-c3089741741=\"\" class=\"ng-star-inserted\"></source-inline-chip></sources-carousel-inline></p><!----><!----><!----><!----><!----><!----><!----><!----></li><li><p data-path-to-node=\"10,3,0\" id=\"p-rc_b3272da9b1c5d217-30\"><span class=\"citation-504 citation-505 citation-506 citation-507 citation-end-507\">Các khiếu nại liên quan đến chương trình phải được gửi tới Công ty Cổ<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"15\"><!----></sup></source-footnote></span><span class=\"citation-504 citation-505 citation-506 citation-end-506\"> phần <source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"16\"><!----></sup></source-footnote></span><span class=\"citation-504 citation-505\">ShopeePay trong vòng 60 ngày kể từ khi phát sinh lỗ</span><span class=\"citation-503 citation-504 citation-505 citation-end-505\">i. Sau thời hạn này, Công ty<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"17\"><!----></sup></source-footnote></span><span class=\"citation-503 citation-504 citation-end-504\"> không tiếp nhận c<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"18\"><!----></sup></source-footnote></span><span class=\"citation-503 citation-end-503\">ác khiếu nại.<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"19\"><!----></sup></source-footnote></span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2291380853=\"\">  <source-inline-chip _ngcontent-ng-c2291380853=\"\" _nghost-ng-c3089741741=\"\" class=\"ng-star-inserted\"></source-inline-chip></sources-carousel-inline></p><!----><!----><!----><!----><!----><!----><!----><!----></li><li><p data-path-to-node=\"10,4,0\" id=\"p-rc_b3272da9b1c5d217-31\"><span class=\"citation-502\">Điều khoả</span><span class=\"citation-498 citation-499 citation-500 citation-501 citation-502 citation-end-502\">n chung của chương trình khuyến mại này là 01 phần thống nhất với Điều khoản sử dụng <source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"20\"><!----></sup></source-footnote></span><span class=\"citation-498 citation-499 citation-500 citation-501 citation-end-501\">ví ShopeePay.<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"21\"><!----></sup></source-footnote></span><span class=\"citation-498 citation-499 citation-500 citation-end-500\"><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"22\"><!----></sup></source-footnote></span><span class=\"citation-498 citation-499 citation-end-499\"><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"23\"><!----></sup></source-footnote></span><span class=\"citation-498 citation-end-498\"><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"24\"><!----></sup></source-footnote></span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2291380853=\"\">  <source-inline-chip _ngcontent-ng-c2291380853=\"\" _nghost-ng-c3089741741=\"\" class=\"ng-star-inserted\"></source-inline-chip></sources-carousel-inline></p><!----><!----><!----><!----><!----><!----><!----><!----></li><li><p data-path-to-node=\"10,5,0\" id=\"p-rc_b3272da9b1c5d217-32\"><span class=\"citation-494 citation-495 citation-496 citation-497 citation-end-497\">Chương trình có thể kết thúc khi ngân sách khuyến mại đã được sử dụng hết. Mọi thông tin sẽ được cập nhật tại trang \"Khuyến Mãi<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"25\"><!----></sup></source-footnote></span><span class=\"citation-494 citation-495 citation-496 citation-end-496\">\" của ShopeePay. Khi có bất kỳ thắc mắc nào liên quan đến chương trình, vui lòng liên hệ tổn<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"26\"><!----></sup></source-footnote></span><span class=\"citation-494 citation-495 citation-end-495\">g đài ShopeePay Việt Nam qua số điện thoại 1900 6906.<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"27\"><!----></sup></source-footnote></span><span class=\"citation-494 citation-end-494\"><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"28\"><!----></sup></source-footnote></span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2291380853=\"\">  <source-inline-chip _ngcontent-ng-c2291380853=\"\" _nghost-ng-c3089741741=\"\" class=\"ng-star-inserted\"></source-inline-chip></sources-carousel-inline></p><!----><!----><!----><!----><!----><!----><!----><!----></li><li><p data-path-to-node=\"10,6,0\" id=\"p-rc_b3272da9b1c5d217-33\"><span class=\"citation-492 citation-493 citation-end-493\">Nếu có tranh<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"29\"><!----></sup></source-footnote></span><span class=\"citation-492\"> chấp </span><span class=\"citation-491 citation-492 citation-end-492\">phát sinh trong toàn bộ chương trình sẽ được xử lý theo quy định của pháp l<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"30\"><!----></sup></source-footnote></span><span class=\"citation-491\">uật. Công ty Cổ phần ShopeePay có quyền từ chối áp dụng ưu đãi cho những người dùng kh</span><span class=\"citation-490 citation-491 citation-end-491\">ông đáp ứng đủ các điều kiệ<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"31\"><!----></sup></source-footnote></span><span class=\"citation-490 citation-end-490\">n tham gia chương trình hoặc gian lận để được hưởng ưu đãi.<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"32\"><!----></sup></source-footnote></span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2291380853=\"\">  <source-inline-chip _ngcontent-ng-c2291380853=\"\" _nghost-ng-c3089741741=\"\" class=\"ng-star-inserted\"></source-inline-chip></sources-carousel-inline></p><!----><!----><!----><!----><!----><!----><!----><!----></li><li><p data-path-to-node=\"10,7,0\" id=\"p-rc_b3272da9b1c5d217-34\"><span class=\"citation-489 citation-end-489\">ShopeePay là đối tác cung cấp dịch vụ trung gian thanh toán. Người dùng tự quyết định và chịu trách nhiệm v<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"33\"><!----></sup></source-footnote></span>ề các quyết định đặt hàng khi sử dụng các dịch vụ tại Galaxy Cinema.<sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2291380853=\"\">  </sources-carousel-inline></p></li></ul>','','https://res.cloudinary.com/dfb5p3kus/image/upload/v1787133920/klrt4lw45cpxqebr31xm.jpg',0,'','Galaxy x ShopeePay Giảm Đến 50K từ 01/08/2026 - 31/08/2026',1,6),(16,'2026-08-19 17:14:50.079895','2026-08-21 10:49:31.633426','admin','duyetht','Hai Combo Conan Mừng Thám Tử Lừng Danh Trở Lại!','<p data-path-to-node=\"1\">Không chỉ một, có đến hai món hàng chính hãng để các fan <em data-path-to-node=\"1\" data-index-in-node=\"57\">Thám Tử Lừng Danh</em> tặng nhau mừng <em data-path-to-node=\"1\" data-index-in-node=\"90\">Thiên Thần Sợ Ngã Trên Xa Lộ</em> ra rạp chiếu phim!</p><p data-path-to-node=\"1\"><img src=\"https://www.galaxycine.vn/media/2026/7/15/hai-combo-conan-mung-tham-tu-lung-danh-tro-lai-2_1784098468223.jpg\"></p><p data-path-to-node=\"2\">Mùa thần Chết Conan quay lại, tặng nhau bùa hộ mệnh có hình bùa thì còn gì tuyệt hơn.</p><p data-path-to-node=\"3\">Lần này, <strong data-path-to-node=\"3\" data-index-in-node=\"9\">Galaxy Cinema</strong> \"lên kệ\" cho Stars tận 4 mẫu <strong data-path-to-node=\"3\" data-index-in-node=\"52\">Conan Omamori Charm</strong> gồm 4 bùa hộ mệnh cứng cáp và sắc nét của thần Chết nhí Edogawa Conan, thiên thần Mori Ran, nhà khoa học Haibara Ai và người chống đoán mệnh Matsuda Jinpei. Omamori đi kèm dây treo đặc trưng, in Hologram bắt sáng và đổi màu huyền ảo.</p><p data-path-to-node=\"4\"><strong data-path-to-node=\"4\" data-index-in-node=\"0\">Conan Omamori Charm</strong> có thể mua lẻ với giá chỉ 85K hoặc mua combo cùng bắp nước với giá siêu ưu đãi, chỉ thêm 50K nữa.</p><p data-path-to-node=\"5\">Chưa hết, <strong data-path-to-node=\"5\" data-index-in-node=\"10\">Galaxy Cinema</strong> còn có <strong data-path-to-node=\"5\" data-index-in-node=\"31\">Conan Popcorn Standee</strong> — với móc khóa Conan x Ran xinh xắn treo cùng standee bắp bắt mắt. Một món đồ vô cùng hợp lý để treo ÔTP. Móc khóa còn có thể tháo rời treo vào balo, túi xách hay bóp viết... tùy thích.</p><p data-path-to-node=\"6\">Standee bắp rạng Conan giá chỉ 129K, thêm 50K là có ngay bắp ngon nước ngọt dùng kèm, quá là hời đúng không Stars?</p><p data-path-to-node=\"7\">Hai Combo Conan sẽ chính thức có mặt tại <strong data-path-to-node=\"7\" data-index-in-node=\"41\">Galaxy Cinema</strong> từ 20.07.</p><p data-path-to-node=\"8\">Đặt online tại <strong data-path-to-node=\"8\" data-index-in-node=\"15\">ĐÂY</strong></p><p data-path-to-node=\"9\"><em data-path-to-node=\"9\" data-index-in-node=\"0\">Lưu ý:</em>\nCombo tạm thời chưa có tại <strong data-path-to-node=\"9\" data-index-in-node=\"34\">Galaxy CineGO! An Lạc</strong>, <strong data-path-to-node=\"9\" data-index-in-node=\"57\">Galaxy Đà Nẵng</strong> và <strong data-path-to-node=\"9\" data-index-in-node=\"75\">Galaxy CineX AEON Mall Thạnh Mỹ</strong>.</p>','','https://res.cloudinary.com/dfb5p3kus/image/upload/v1787134429/dsbevwwpcsnmnyn2been.jpg',0,'','Hai Combo Conan Mừng Thám Tử Lừng Danh Trở Lại!',1,6),(17,'2026-08-19 17:17:12.716935','2026-08-21 16:25:26.806037','admin','duyetht','Bắp Ngọt Vị Cốm – Hương Vị Mùa Thu Hà Nội Giữa Lòng Rạp Chiếu','<p data-path-to-node=\"1\">Nghe đồn ở đâu đó vừa có vị Bắp cốm, nhưng rạp <strong data-path-to-node=\"1\" data-index-in-node=\"47\">Galaxy Cinema</strong> đã thơm lừng mùi cốm từ lâu rồi nè!</p><p data-path-to-node=\"1\"><img src=\"https://www.galaxycine.vn/media/2026/8/10/bap-com-galaxy-cinema-2_1786350537919.jpg\"></p><p data-path-to-node=\"6\" id=\"p-rc_85bc6343056181ab-45\">Mùa cốm đến sớm không chỉ ở Hà Nội, mà lan tỏa đến các rạp <strong data-path-to-node=\"6\" data-index-in-node=\"59\">Galaxy Cinema</strong> <span class=\"citation-570 citation-end-570\">trên mọi miền tổ quốc. Nhắc nhẹ các Stars ra rạp đừng quên chọn Bắp vị Cốm để hòa cùng không khí mùa thu Hà Nội man mát nhé!<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"1\"><!----></sup></source-footnote></span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2291380853=\"\">  <source-inline-chip _ngcontent-ng-c2291380853=\"\" _nghost-ng-c3089741741=\"\" class=\"ng-star-inserted\"></source-inline-chip></sources-carousel-inline></p><div _ngcontent-ng-c3089741741=\"\" class=\"source-inline-chip-container luminous-sources ng-star-inserted\"><span class=\"citation-569 citation-end-569\">Bắp ngọt vị cốm Hà Nội - Có mặt<source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2260573510=\"\"><sup _ngcontent-ng-c2260573510=\"\" class=\"superscript\" data-turn-source-index=\"2\"><!----></sup></source-footnote></span> từ 15.08.2026 tại các cụm rạp <strong data-path-to-node=\"7\" data-index-in-node=\"62\">Galaxy Cinema</strong> toàn quốc.<sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c2291380853=\"\">  </sources-carousel-inline></div>','','https://res.cloudinary.com/dfb5p3kus/image/upload/v1787134615/wabxd9pfmapunbpzxlsf.jpg',0,'','Bắp Ngọt Vị Cốm – Hương Vị Mùa Thu Hà Nội Giữa Lòng Rạp Chiếu',1,6),(18,'2026-08-19 17:31:58.923993','2026-08-19 17:35:01.413257','duyetht','admin','','','','',3,NULL,'',0,0),(19,'2026-08-19 17:34:30.627563','2026-08-21 10:53:29.508375','duyetht','admin','Khoảng cách thế hệ là đề tài cũ trong dòng phim Việt. Mỗi năm, từ truyền hình đến điện ảnh, mâu thuẫn gia đình cha mẹ - con cái, ông bà – cháu... lên màn ảnh nhiều không đếm xuể. Thế nhưng, những bộ phim mới vẫn luôn thu hút sự chú ý từ công chúng bởi tính gần gũi, dễ cảm.','<p data-path-to-node=\"1\"><strong data-path-to-node=\"1\" data-index-in-node=\"0\">Nghỉ Hè Sợ Nghỉ Hưu</strong> cũng chọn đề tài hấp dẫn này. Nhằm tăng phần mới mẻ, đạo diễn kiêm biên kịch Huỳnh Lập lồng ghép thêm nội dung liên quan đến lòng yêu nước và mảng miếng sở trường - tâm linh.</p><p data-path-to-node=\"1\" style=\"text-align: center;\"><img src=\"https://www.galaxycine.vn/media/2026/8/19/nghi-he-so-nghi-huu-no-luc-lam-moi-de-tai-cu-cua-hunh-lap-6_1787110890210.jpg\"></p><p data-path-to-node=\"2\">Đang trăn trở “Nếu cả đời này không rực rỡ thì sao?”, chàng trai trẻ sắp tốt nghiệp đại học Trí Bình quyết tâm khởi nghiệp bằng cách mở quán cà phê tại nhà. Bị ba mẹ từ chối, Trí Bình biết chủ nhân thật sự của ngôi nhà là ông nội. Thế là, cậu quyết định tò tò chạy theo, xin ông cho phép. Tuy nhiên, sau vài ngày ở cùng người ông vốn xa cách lâu năm, Trí Bình lờ mờ phát hiện, ông mình bị... ma ám!</p><p data-path-to-node=\"3\">Nỗ lực “cứu” ông, Trí Bình liên tiếp gây nên loạt tình huống dở khóc dở cười!</p><p data-path-to-node=\"3\" style=\"text-align: center;\"><img src=\"https://www.galaxycine.vn/media/2026/8/19/nghi-he-so-nghi-huu-no-luc-lam-moi-de-tai-cu-cua-hunh-lap-3_1787110973766.jpg\"></p><p data-path-to-node=\"4\">Năm ngoái, Huỳnh Lập gây bão bằng <em data-path-to-node=\"4\" data-index-in-node=\"34\">Nhà Gia Tiên</em>, đạt doanh thu 240 tỷ đồng. Bộ phim do Phương Mỹ Chi đóng chính lồng ghép thành công câu chuyện gia đình cảm động với đề tài tâm linh. Sau cú hích phòng vé ấy, Huỳnh Lập nảy ra ý tưởng thực hiện <strong data-path-to-node=\"4\" data-index-in-node=\"242\">Nghỉ Hè Sợ Nghỉ Hưu</strong> trong một lần thăm Côn Đảo và viếng thăm những ngôi mộ chưa xác định danh tính. Thời gian tham gia chương trình ý nghĩa – Sao Nhập Ngũ giúp anh có thêm trải nghiệm về cuộc sống người lính. Hơn hết, không khí rộn ràng, tinh thần yêu nước của thế hệ trẻ qua hai dịp A50 và A80 năm ngoái củng cố niềm tin về bộ phim.</p>','','https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?q=80&w=800',1,'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?q=80&w=800','[Review] Nghỉ Hè Sợ Nghỉ Hưu: Nỗ Lực Làm Mới Đề Tài Cũ Của Huỳnh Lập',0,43),(20,'2026-08-19 22:16:08.490976','2026-08-21 11:37:11.410969','duyetht','admin','','','','https://res.cloudinary.com/dfb5p3kus/image/upload/v1787152563/onz2clboe0xu74jwniai.webp',1,NULL,'Bộ phim các bạn mong chờ nhất là gì?',0,22),(21,'2026-08-19 22:35:30.037654','2026-08-21 12:38:31.563130','duyetht','admin','','','','https://res.cloudinary.com/dfb5p3kus/image/upload/v1787153707/ikvn1j2ostwa77r897zx.webp',1,NULL,'Hộ linh tráng sĩ bộ phim lịch sử hào vùng Việt Nam ta',0,18),(22,'2026-08-19 22:36:29.096346','2026-08-21 16:27:02.099656','duyetht','admin','','','','https://res.cloudinary.com/dfb5p3kus/image/upload/v1787153785/ol1x3whssfvppytvvzet.jpg',1,NULL,'Liệu nhện nhọ có thể lấy lại ký ức của người trong tym',0,115),(23,'2026-08-21 00:20:46.000000','2026-08-21 11:52:58.534595',NULL,'admin','Thứ Ba Vui Vẻ - Giá vé xem phim cực ưu đãi chỉ từ 45.000đ dành cho mọi khán giả tại rạp World Cinema.','<p>Thưởng thức các siêu phẩm điện ảnh với mức giá siêu hạt dẻ chỉ từ 45k vào mỗi Thứ Ba hàng tuần tại tất cả các cụm rạp World Cinema trên toàn quốc!</p>',NULL,'/img/hinh-1-14.jpg',0,'/img/hinh-1-14.jpg','Happy Day - Vé Chỉ Từ 45K',1,1257),(24,'2026-08-21 00:20:46.000000','2026-08-21 01:15:03.457908',NULL,'duyetht','Quyền lợi và chính sách tích điểm, quà tặng sinh nhật, vé xem phim miễn phí dành riêng cho thành viên World Cinema.','<p>Trở thành thành viên World Cinema ngay hôm nay để nhận vô vàn đặc quyền hấp dẫn: tích điểm đổi vé xem phim, bắp nước và quà sinh nhật đặc biệt!</p>',NULL,'/img/nghi-he-so-nghi-huu-1_1786436532090.jpg',0,'/img/nghi-he-so-nghi-huu-1_1786436532090.jpg','Ưu Đãi Thành Viên World Cinema 2026',1,2102),(25,'2026-08-21 00:20:46.000000',NULL,NULL,NULL,'Ngày Tri Ân Khách Hàng - Đồng giá vé 45K/vé 2D và miễn phí 1 lần châm thêm bắp & nước vào Thứ Hai đầu tiên mỗi tháng.','<p>World Cinema gửi lời tri ân sâu sắc đến quý khách hàng với chương trình đồng giá 45K và refill bắp nước miễn phí vào Thứ Hai đầu tiên mỗi tháng.</p>',NULL,'/img/insidious-sneak-2048_1786436889562.jpg',0,'/img/insidious-sneak-2048_1786436889562.jpg','Ngày Tri Ân Của World Cinema - Ngày Thứ Hai ĐẦU TIÊN Mỗi Tháng',1,980);
